-- =====================================================================
-- HERITAGE HOMMAGE — QG 008, LOT 3 — v4 : slug public généré à la première publication
-- =====================================================================
-- Append-only : ce fichier AJOUTE deux fonctions ; il ne modifie ni v3
-- (20261102100000) ni v2, qui restent en place, inchangées.
--
-- Constat (reprise S1 du 2026-11-03) : memorials.slug est nullable depuis
-- 20260901120000 (« NULL until the real slug is generated by the publication
-- flow »), aucun rôle ne peut l'écrire, et aucune génération n'existe. v3 et
-- v2 EXIGENT un slug non vide et le comparent : aucune publication réelle
-- n'était possible.
--
-- Décisions QG / PO (2026-11-03) : slug public OPAQUE (aucun nom de la
-- personne défunte), généré automatiquement et de façon STABLE lors de la
-- première publication, jamais saisi par la famille.
--
-- 1. memorial_public_slug_v1(id, longueur) : fonction PURE. Le slug est le
--    préfixe hexadécimal (12 à 64 caractères) du SHA-256 d'une chaîne fixe
--    préfixée de l'identifiant du mémorial. Même identifiant => même slug,
--    à chaque appel : un refus (transaction annulée) suivi d'une nouvelle
--    tentative redonne EXACTEMENT le même slug ; il n'est jamais
--    « régénéré ». Aucune donnée personnelle.
--
-- 2. commit_memorial_publication_v4 : mêmes paramètres que v3, mais
--    p_expected_slug peut être NULL (« le mémorial n'a pas encore de slug »).
--    Sous le verrou FOR UPDATE de la ligne du mémorial :
--      - propriétaire vérifié (42501, opaque) AVANT toute écriture ;
--      - slug NULL : permis seulement pour une première publication (draft,
--        jamais publié) et si l'appelant n'en attendait pas ; le premier
--        candidat libre (12, 16, … 64 caractères ; verrou consultatif par
--        candidat) est écrit dans la MÊME transaction ;
--      - slug présent : s'il est attendu, il doit être égal (sinon 40001) ;
--        s'il n'est pas attendu (NULL, ex. second clic préparé avant la
--        première publication), le slug enregistré est repris ;
--    puis v3 INCHANGÉE (révision, contenu, photo principale HD422, niveau,
--    langue, skin, variante, slug, v2 : CAS, galerie, entitlement gratuit,
--    instantané, événement) reçoit le slug résolu. Toute erreur annule tout,
--    slug compris. Le slug résolu est renvoyé.
--    Double clic / onglets concurrents : sérialisés par le verrou ; le second
--    appel trouve published + slug enregistré, et v3 démontre l'identité
--    (already_published) ou refuse (40001).
-- service_role seul, SECURITY DEFINER, search_path vide (comme v3).
-- Aucune ouverture de droit d'écriture sur memorials.slug.
-- =====================================================================

create or replace function public.memorial_public_slug_v1(p_memorial_id uuid, p_length integer)
returns text
language sql
immutable
strict
set search_path = ''
as $$
  select case
    when p_length between 12 and 64
      then pg_catalog.substr(
             pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to('heritage-public-slug-v1:' || p_memorial_id::text, 'UTF8')), 'hex'),
             1, p_length)
  end;
$$;

comment on function public.memorial_public_slug_v1(uuid, integer) is
  'QG 008 Lot 3 v4. Slug public OPAQUE et déterministe d''un mémorial : préfixe hexadécimal (12 à 64 caractères) du SHA-256 de « heritage-public-slug-v1:<id> ». Aucune donnée personnelle. NULL hors bornes. Appelée uniquement par commit_memorial_publication_v4.';

revoke all on function public.memorial_public_slug_v1(uuid, integer) from public, anon, authenticated, service_role;

create or replace function public.commit_memorial_publication_v4(
  p_memorial_id uuid,
  p_owner_id uuid,
  p_expected_revision bigint,
  p_expected_language text,
  p_expected_skin text,
  p_expected_skin_variant text,
  p_expected_slug text,
  p_expected_access_level text,
  p_expected_content jsonb,
  p_published_content jsonb
)
returns table (published_at timestamptz, first_published_at timestamptz, revision bigint, outcome text, slug text)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_memorial public.memorials%rowtype;
  v_slug text;
  v_candidate text;
  v_length integer;
begin
  -- Le slug attendu peut être NULL (pas encore de slug), jamais vide.
  if p_memorial_id is null
     or p_owner_id is null
     or (p_expected_slug is not null and nullif(btrim(p_expected_slug), '') is null) then
    raise exception 'invalid memorial publication request' using errcode = '22023';
  end if;

  select * into v_memorial
    from public.memorials
   where id = p_memorial_id
   for update;
  if not found or v_memorial.owner_id is distinct from p_owner_id then
    raise exception 'memorial publication refused' using errcode = '42501';
  end if;

  if v_memorial.slug is null then
    -- Génération : première publication seulement, et l'appelant n'attendait pas de slug.
    if p_expected_slug is not null
       or v_memorial.status is distinct from 'draft'
       or v_memorial.first_published_at is not null then
      raise exception 'memorial lifecycle changed' using errcode = '40001';
    end if;
    v_length := 12;
    while v_length <= 64 loop
      v_candidate := public.memorial_public_slug_v1(p_memorial_id, v_length);
      perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('heritage-public-slug:' || v_candidate, 0));
      if not exists (select 1 from public.memorials m where m.slug = v_candidate and m.id <> p_memorial_id) then
        v_slug := v_candidate;
        exit;
      end if;
      v_length := v_length + 4;
    end loop;
    if v_slug is null then
      raise exception 'memorial public slug unavailable' using errcode = '40001';
    end if;
    update public.memorials
       set slug = v_slug
     where id = p_memorial_id;
  else
    if p_expected_slug is not null and p_expected_slug is distinct from v_memorial.slug then
      raise exception 'memorial lifecycle changed' using errcode = '40001';
    end if;
    v_slug := v_memorial.slug;
  end if;

  -- v3 inchangée, avec le slug résolu (même transaction : tout ou rien).
  return query
    select v3.published_at, v3.first_published_at, v3.revision, v3.outcome, v_slug
      from public.commit_memorial_publication_v3(
        p_memorial_id,
        p_owner_id,
        p_expected_revision,
        p_expected_language,
        p_expected_skin,
        p_expected_skin_variant,
        v_slug,
        p_expected_access_level,
        p_expected_content,
        p_published_content
      ) as v3;
end;
$$;

comment on function public.commit_memorial_publication_v4(uuid, uuid, bigint, text, text, text, text, text, jsonb, jsonb) is
  'QG 008 Lot 3 v4. Première publication depuis l''aperçu avec slug public : sous verrou du mémorial et après contrôle du propriétaire, génère le slug opaque et stable (memorial_public_slug_v1, premier candidat libre de 12 à 64 caractères) si le mémorial n''en a pas et qu''il s''agit d''une première publication, ou reprend le slug enregistré ; puis commit_memorial_publication_v3 inchangée, dans la même transaction (tout ou rien, slug compris). p_expected_slug NULL = aucun slug attendu. Renvoie le slug résolu. service_role seul.';

revoke all on function public.commit_memorial_publication_v4(uuid, uuid, bigint, text, text, text, text, text, jsonb, jsonb) from public, anon, authenticated;
grant execute on function public.commit_memorial_publication_v4(uuid, uuid, bigint, text, text, text, text, text, jsonb, jsonb) to service_role;
